function printBlanks(keys){
  const L = FBLANKS.filter(b=>(keys || []).includes(b.k)); if (!L.length){ toast('Позначте хоча б один бланк'); return false; }
  let framed = false; try{ framed = window.top !== window.self; }catch(e){ framed = true; }
  if (framed){ toast('В онлайн-версії друк заблоковано. Відкрийте програму окремою сторінкою або офлайн-файлом', 4000); return false; }
  const P = $('#print'); P.innerHTML = '';
  L.forEach(b=>{ const d = document.createElement('div'); d.className = b.cls; d.innerHTML = b.html; P.append(d); });
  toast('Порожні бланки: ' + L.length + '. Щоб отримати PDF, у вікні друку виберіть «Зберегти як PDF»', 3500);
  window.print(); return true;
}
function blanksDialog(){
  const old = document.getElementById('fbPick'); if (old) old.remove();
  const back = document.activeElement;
  const close = () => { box.remove(); try{ if (back && back.focus) back.focus(); }catch(e){} };
  const rows = FBLANKS.map(b=>h('label', {for:'fb_' + b.k}, h('input', {type:'checkbox', id:'fb_' + b.k, value:b.k}), b.t));
  const go = () => { const k = [...box.querySelectorAll('input:checked')].map(i=>i.value); if (!k.length){ toast('Позначте хоча б один бланк'); return; } close(); printBlanks(k); };
  const box = h('div', {id:'fbPick', class:'modal', role:'dialog', 'aria-modal':'true', 'aria-labelledby':'fbPickT'},
    h('div', {class:'mcard'},
      h('div', {class:'ph'}, h('h2', {id:'fbPickT'}, 'Порожні бланки для друку'), h('button', {type:'button', class:'btn', onclick:close}, 'Закрити ✕')),
      h('p', {class:'chips-hint'}, 'Без даних пацієнта — для заповнення ручкою: варіанти підкреслити, значення вписати. Кожен бланк починається з нового аркуша А4. Епікриз 003/о — дві сторінки (друк з двох боків).'),
      h('div', {class:'fbrows'}, ...rows),
      h('div', {class:'acts2'}, h('button', {type:'button', class:'btn primary', onclick:go}, '🖨 Друкувати вибрані'))));
  box.addEventListener('click', e=>{ if (e.target === box) close(); });
  box.addEventListener('keydown', e=>{ if (e.key === 'Escape'){ e.stopPropagation(); close(); } });
  document.body.append(box); const f = box.querySelector('input'); if (f) f.focus();
}
/* пункт меню «⋯» поруч із «🖨 Кілька документів» */
try{
  document.querySelectorAll('.more-dd .mmenu').forEach(menu=>{
    const multi = [...menu.querySelectorAll('button')].find(b=>/^🖨 Кілька документів/.test(b.textContent.trim()));
    if (!multi || menu.querySelector('.fbbtn')) return;
    const b = h('button', {type:'button', class:'more fbbtn', role:'menuitem', title:'Надрукувати порожні щоденники й епікризи для заповнення ручкою', onclick:()=>{ const dd = menu.closest('details'); if (dd) dd.open = false; blanksDialog(); }}, '🖨 Порожні бланки');
    multi.after(b);
  });
}catch(e){}
